changeSet.rollback:
create or alter procedure [fusion].[ProcessFusionCacheInQueue] @FusionID int as begin set nocount, ansi_padding on; set ansi_warnings on;
update FusionAttribute set TextPath = utility.GetBreadcrumbStringWrapper('FusionAttribute', ID, '.') where FusionID = @FusionID and deleted = 0
declare @fusionTypeId int;
select @fusionTypeId = fusiontypeid from Fusion where ID = @FusionID;
declare @executionUid uniqueidentifier = newid(), @dummyAssetTypeUid uniqueidentifier = newid() insert into [api].[Execution] ([ExecutionID], [ResourceID], [Total], [Processed], [Error], [StartedOn], [State], [MarkedForProcessing], Fields) values (@executionUid, 0, 0, 0, 0, getutcdate(), 1, 1, '{"AssetTypeUid":"' + cast(@dummyAssetTypeUid as varchar(50)) + '"}')
insert into [api].[ExecutionAsset] ( [ExecutionID], [ItemNumber], [AssetID], [UpdateGraph] ) select @executionUid, ROW_NUMBER() over (order by A.ID), A.ID, 1 from [fusion].[result] R inner join [fusion].[Execution] E on R.ExecutionID = E.ID and E.FusionID = @FusionID and E.DateCompleted >= DATEADD(HH, -6, getutcdate()) inner join Asset A on A.Object = 'FusionAttribute' and A.ObjectID = R.FusionAttributeID group by A.ID;
merge [graph].[AssetNode] T using ( select distinct EA.AssetID as ID, A.Uid, A.AssetTypeID, T.Uid as AssetTypeUid, A.State, A.UpdatedOn, T.Class from [api].[ExecutionAsset] EA inner join Asset A on A.ID = EA.AssetID inner join AssetType T on T.ID = A.AssetTypeID where EA.ExecutionID = @executionUid ) S on (T.ID = S.ID) when matched then update set T.State = S.State, T.UpdatedOn = S.UpdatedOn when not matched by target then insert (ID, Uid, AssetTypeID, AssetTypeUid, State, UpdatedOn, Class) values (S.ID, S.Uid, S.AssetTypeID, S.AssetTypeUid, S.State, S.UpdatedOn, S.Class);
merge graph.AssetEdge T using ( select distinct SG.$node_id as from_id, OG.$node_id as to_id, I.ID, I.[Uid], I.IntersectTypeID, T.[Uid] as IntersectTypeUid, T.PredicateID, P.[Uid] as PredicateUid, P.[Type] as PredicateType, I.[State], coalesce(I.UpdatedOn, I.CreatedOn, getutcdate()) as UpdatedOn from [Intersect] I inner join Asset SA on SA.[Object] = I.[Subject] and SA.ObjectID = I.SubjectID inner join graph.AssetNode SG on SG.ID = SA.ID inner join Asset OA on OA.[Object] = I.[Object] and OA.ObjectID = I.ObjectID inner join graph.AssetNode OG on OG.ID = OA.ID inner join IntersectType T on T.ID = I.IntersectTypeID inner join [Predicate] P on P.ID = T.PredicateID inner join [api].[ExecutionAsset] EA on (EA.AssetID = SA.ID or EA.AssetID = OA.ID) and EA.ExecutionID = @executionUid ) S on (S.ID = T.ID and S.from_id = T.$from_id and S.to_id = T.$to_id) when matched then update set T.IntersectTypeID = S.IntersectTypeID, T.IntersectTypeUid = S.IntersectTypeUid, T.PredicateID = S.PredicateID, T.PredicateUid = S.PredicateUid, T.PredicateType = S.PredicateType, T.[State] = S.[State] when not matched by target then insert ($from_id, $to_id, ID, Uid, IntersectTypeID, IntersectTypeUid, PredicateID, Properties, PredicateUid, PredicateType, [State], UpdatedOn) values (from_id, to_id, ID, Uid, IntersectTypeID, IntersectTypeUid, PredicateID, '<properties/>', PredicateUid, PredicateType, [State], UpdatedOn);
exec graph.UpdateGraphTableHierarchyBy @executionUid, null, null
delete [api].[ExecutionAsset] where ExecutionID = @executionUid; delete [api].[Execution] where ExecutionID = @executionUid; end
